    S0, S1, S2, S3, S4 = 0, 1, 2, 3, 4
    state = S0
    start_shifting = 0
    out = []
    for row in vectors:
        reset = row.get('reset', 0)
        data = row.get('data', 0)
        # R1: reset == 1 -> start_shifting = 0 (priority 1)
        if reset == 1:
            start_shifting = 0
            state = S0
        else:
            # R2: state == S4 -> start_shifting = 1 (priority 2)
            if state == S4:
                start_shifting = 1
            # R3: state == S3 and data == 1 -> start_shifting = 1 (priority 3)
            elif state == S3 and data == 1:
                start_shifting = 1
                state = S4
            # R4: otherwise start_shifting = 0 (priority 4)
            else:
                start_shifting = 0
                # state transitions for sequence detection
                if state == S0:
                    if data == 1:
                        state = S1
                elif state == S1:
                    if data == 1:
                        state = S2
                    else:
                        state = S0
                elif state == S2:
                    if data == 0:
                        state = S3
                    else:
                        state = S2
                elif state == S3:
                    if data == 1:
                        state = S4
                    else:
                        state = S0
        out.append({'start_shifting': start_shifting})
    return out
